<?php require_once dirname(__DIR__).'/core/bootstrap.php'; if(is_admin())redirect('/admin/'); $gateHash=setting($pdo,'admin_gate_hash',''); if(isset($_GET['gate']) && is_string($_GET['gate']) && $gateHash && password_verify($_GET['gate'],$gateHash)){$_SESSION['admin_gate_ok']=1; redirect('/admin/login.php');} if(empty($_SESSION['admin_gate_ok'])){http_response_code(404);exit('Not Found');} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$ip=client_ip();if(login_rate_limited($pdo,$ip)){$error='تلاش‌های ناموفق زیاد بوده؛ ۱۵ دقیقه بعد دوباره امتحان کنید.';}else{$u=trim($_POST['username']??'');$p=(string)($_POST['password']??'');$s=$pdo->prepare('SELECT * FROM admins WHERE username=? LIMIT 1');$s->execute([$u]);$a=$s->fetch();if($a&&password_verify($p,$a['password_hash'])){clear_login_failures($pdo,$ip);session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$pdo->prepare('UPDATE admins SET last_login_at=NOW() WHERE id=?')->execute([$a['id']]);redirect('/admin/');}record_login_failure($pdo,$ip);$error='نام کاربری یا رمز اشتباه است.';}}?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>ورود</title><style>body{font-family:Tahoma;background:#0b1020;color:#fff;min-height:100vh;display:grid;place-items:center;margin:0}.c{width:min(390px,90%);background:#121a2c;border:1px solid #293650;padding:24px;border-radius:20px}input{width:100%;box-sizing:border-box;padding:13px;border-radius:11px;border:1px solid #34415e;background:#0d1424;color:#fff;margin:6px 0 14px}button{width:100%;padding:13px;border:0;border-radius:11px;background:#7c96ff;font-weight:bold}.e{background:#48242d;padding:10px;border-radius:10px}</style></head><body><div class="c"><h2>ورود مدیر</h2><?php if($error):?><p class="e"><?=e($error)?></p><?php endif?><form method="post"><?=csrf_field()?><label>نام کاربری</label><input name="username" autocomplete="u